import com.amazon.ion.*;
import com.amazon.ion.system.*;
import java.nio.file.*;
IonSystem sys = IonSystemBuilder.standard().build();
var dir = Paths.get(System.getProperty("user.dir"), "w9a-t1-ionbin");
try (var s = Files.list(dir)) {
  for (Path p : s.filter(x -> x.toString().endsWith(".ion")).sorted().toList()) {
    byte[] b = Files.readAllBytes(p);
    StringBuilder sb = new StringBuilder();
    try (IonReader r = IonReaderBuilder.standard().build(b); IonWriter w = IonTextWriterBuilder.minimal().build(sb)) { w.writeValues(r); }
    System.out.println("TEXT\t" + p.getFileName() + "\t" + sb.toString().replace("\n", "\\n"));
    var vals = new java.util.ArrayList<Object>();
    try (var in = new java.io.ByteArrayInputStream(b)) { io.kestra.core.serializers.FileSerde.read(in, vals::add); }
    for (Object o : vals) System.out.println("JAVA\t" + p.getFileName() + "\t" + (o == null ? "null" : o.getClass().getName()) + "\t" + o + "\t" + (o instanceof java.util.Map<?,?> m ? m.values().stream().map(v -> v == null ? "null" : v.getClass().getSimpleName()).toList() : ""));
  }
}
/exit
